"use client"

import { useMemo, useState } from "react"
import type { ColumnDef } from "@tanstack/react-table"

import { Badge } from "@/components/ui/badge"
import { TableSortable } from "@/components/table-sortable"
import { cn } from "@/lib/utils"
import type { AdminUserRow, UserRole, UserStatus } from "../_data/users-data"
import { ADMIN_USERS, ROLE_LABEL, STATUS_LABEL, TEAM_FACETS } from "../_data/users-data"
import { TeamFacetedFilter } from "./team-faceted-filter"
import { USER_SEARCH_FILTER_DEFAULT, UserSearchFilter, type UserSearchFilterValue } from "./user-search-filter"

const STATUS_BADGE_VARIANT: Record<UserStatus, "default" | "secondary" | "destructive" | "outline"> = {
  active: "default",
  invited: "secondary",
  suspended: "destructive",
}

const ROLE_BADGE_VARIANT: Record<UserRole, "default" | "secondary" | "outline"> = {
  admin: "default",
  editor: "secondary",
  viewer: "outline",
}

const COLUMNS: ColumnDef<AdminUserRow, unknown>[] = [
  {
    accessorKey: "name",
    header: "이름",
    cell: ({ row }) => (
      <div className="flex flex-col">
        <span className="font-medium text-foreground">{row.original.name}</span>
        <span className="text-xs text-muted-foreground">{row.original.email}</span>
      </div>
    ),
  },
  {
    accessorKey: "role",
    header: "역할",
    cell: ({ row }) => (
      <Badge variant={ROLE_BADGE_VARIANT[row.original.role]}>{ROLE_LABEL[row.original.role]}</Badge>
    ),
  },
  {
    accessorKey: "status",
    header: "상태",
    cell: ({ row }) => (
      <Badge variant={STATUS_BADGE_VARIANT[row.original.status]}>{STATUS_LABEL[row.original.status]}</Badge>
    ),
  },
  {
    accessorKey: "team",
    header: "팀",
    cell: ({ row }) => <span className="text-muted-foreground">{row.original.team}</span>,
  },
  {
    accessorKey: "joinedAt",
    header: "가입일",
    cell: ({ row }) => <span className="tabular-nums text-muted-foreground">{row.original.joinedAt}</span>,
  },
]

const TEAM_KEY_BY_LABEL: Record<string, string> = Object.fromEntries(
  TEAM_FACETS.map((facet) => [facet.label, facet.key]),
)

/**
 * "데이터 관리" 페이지의 상호작용 오케스트레이터 — 검색/역할/상태 필터
 * (UserSearchFilter), 팀 칩 필터(TeamFacetedFilter), 정렬 가능한 테이블
 * (components/table-sortable.tsx)을 하나의 controlled state로 묶는다.
 */
export function DataExplorer() {
  const [filter, setFilter] = useState<UserSearchFilterValue>(USER_SEARCH_FILTER_DEFAULT)
  const [team, setTeam] = useState("")

  const teamFiltered = useMemo(
    () => (team ? ADMIN_USERS.filter((user) => TEAM_KEY_BY_LABEL[user.team] === team) : ADMIN_USERS),
    [team],
  )

  const teamCounts = useMemo(() => {
    const counts: Record<string, number> = {}
    for (const facet of TEAM_FACETS) {
      counts[facet.key] = ADMIN_USERS.filter((user) => TEAM_KEY_BY_LABEL[user.team] === facet.key).length
    }
    return counts
  }, [])

  const filteredRows = useMemo(() => {
    const search = filter.search.trim().toLowerCase()
    return teamFiltered.filter((user) => {
      if (filter.role !== "all" && user.role !== filter.role) return false
      if (filter.status !== "all" && user.status !== filter.status) return false
      if (search && !`${user.name} ${user.email}`.toLowerCase().includes(search)) return false
      return true
    })
  }, [teamFiltered, filter])

  return (
    <div className={cn("flex w-full flex-col gap-4")}>
      <UserSearchFilter value={filter} onChange={setFilter} />
      <TeamFacetedFilter
        groups={TEAM_FACETS}
        counts={teamCounts}
        totalCount={ADMIN_USERS.length}
        value={team}
        onChange={setTeam}
      />
      <TableSortable data={filteredRows} columns={COLUMNS} getRowId={(row) => row.id} maxBodyHeight="28rem" />
    </div>
  )
}

import { ArrowDownRightIcon, ArrowUpRightIcon, MinusIcon } from "@phosphor-icons/react/dist/ssr"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import type { KpiMetric } from "../_data/dashboard-data"

const TREND_ICON = {
  up: ArrowUpRightIcon,
  down: ArrowDownRightIcon,
  flat: MinusIcon,
} as const

const TREND_TONE: Record<KpiMetric["trend"], string> = {
  up: "text-success",
  down: "text-destructive",
  flat: "text-muted-foreground",
}

/** 대시보드 상단 KPI 카드 — 값 + 전주 대비 델타(추세 아이콘·색)를 보여준다. */
export function KpiCard({ metric }: Readonly<{ metric: KpiMetric }>) {
  const TrendIcon = TREND_ICON[metric.trend]
  const tone = TREND_TONE[metric.trend]

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-xs font-medium text-muted-foreground">{metric.label}</CardTitle>
      </CardHeader>
      <CardContent className="flex flex-col gap-1.5">
        <span className="text-2xl font-semibold tracking-tight tabular-nums">{metric.value}</span>
        <span className={cn("flex items-center gap-1 text-xs font-medium", tone)}>
          <TrendIcon size={12} weight="bold" />
          {metric.delta !== 0 ? `${Math.abs(metric.delta)}%` : ""} {metric.deltaLabel}
        </span>
      </CardContent>
    </Card>
  )
}

import type { ReactNode } from "react"

import { Badge } from "@/components/ui/badge"

interface PageHeadingProps {
  eyebrow: string
  title: string
  description: string
  action?: ReactNode
}

/** 템플릿 4개 페이지가 공유하는 타이틀 블록 — badge → h1 → 설명(app-shell-samples.tsx 규약). */
export function PageHeading({ eyebrow, title, description, action }: Readonly<PageHeadingProps>) {
  return (
    <section className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
      <div className="flex flex-col gap-3">
        <Badge variant="secondary" className="w-fit">
          {eyebrow}
        </Badge>
        <h1 className="text-xl font-semibold tracking-tight md:text-2xl">{title}</h1>
        <p className="max-w-prose text-sm text-muted-foreground">{description}</p>
      </div>
      {action ? <div className="shrink-0">{action}</div> : null}
    </section>
  )
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import type { ServiceStatus, StatusWidgetItem } from "../_data/dashboard-data"

const STATUS_DOT: Record<ServiceStatus, string> = {
  operational: "bg-success",
  degraded: "bg-warning",
  outage: "bg-destructive",
}

const STATUS_LABEL: Record<ServiceStatus, string> = {
  operational: "정상",
  degraded: "지연",
  outage: "장애",
}

const STATUS_TONE: Record<ServiceStatus, string> = {
  operational: "text-success",
  degraded: "text-warning",
  outage: "text-destructive",
}

/** 서비스별 상태 점 + 지연시간 + 가동률을 보여주는 상태 위젯. */
export function StatusWidget({ items }: Readonly<{ items: StatusWidgetItem[] }>) {
  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-sm">서비스 상태</CardTitle>
      </CardHeader>
      <CardContent>
        <ul className="flex flex-col divide-y divide-border">
          {items.map((item) => (
            <li key={item.id} className="flex items-center justify-between gap-3 py-2 first:pt-0 last:pb-0">
              <div className="flex items-center gap-2">
                <span
                  aria-hidden
                  className={cn("h-2 w-2 shrink-0 rounded-full", STATUS_DOT[item.status])}
                />
                <span className="text-sm text-foreground">{item.name}</span>
              </div>
              <div className="flex items-center gap-3 text-xs text-muted-foreground">
                <span className="tabular-nums">{item.uptime}</span>
                <span className={cn("w-10 text-right font-medium", STATUS_TONE[item.status])}>
                  {STATUS_LABEL[item.status]}
                </span>
              </div>
            </li>
          ))}
        </ul>
      </CardContent>
    </Card>
  )
}

"use client"

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

export interface FacetGroup {
  key: string
  label: string
  /** themes 토큰 접미사(chart-1 등) — 하드코딩 hex 대신 CSS 변수 기반 클래스로 렌더한다. */
  color: "chart-1" | "chart-2" | "chart-3" | "chart-4" | "chart-5"
}

const COLOR_CLASS: Record<FacetGroup["color"], { bg: string; border: string }> = {
  "chart-1": { bg: "bg-chart-1", border: "border-chart-1" },
  "chart-2": { bg: "bg-chart-2", border: "border-chart-2" },
  "chart-3": { bg: "bg-chart-3", border: "border-chart-3" },
  "chart-4": { bg: "bg-chart-4", border: "border-chart-4" },
  "chart-5": { bg: "bg-chart-5", border: "border-chart-5" },
}

interface TeamFacetedFilterProps {
  groups: FacetGroup[]
  counts: Record<string, number>
  totalCount: number
  value: string
  onChange: (next: string) => void
}

/**
 * components/patterns/faceted-filter/faceted-filter-demo.tsx를 일반화한 버전 —
 * 원본 데모는 그룹 색을 인라인 hex(style={{backgroundColor}})로 하드코딩했지만,
 * 이 템플릿은 하드코딩색 0 규칙을 지키기 위해 chart-1..5 CSS 변수 기반 유틸리티
 * 클래스만 사용한다(themes/*.ts가 단일 진실원천).
 */
export function TeamFacetedFilter({ groups, counts, totalCount, value, onChange }: Readonly<TeamFacetedFilterProps>) {
  return (
    <div className="flex flex-wrap items-center gap-1.5 overflow-x-auto pb-1">
      <FacetChip active={value === ""} onClick={() => onChange("")}>
        전체
        <CountBadge active={value === ""}>{totalCount}</CountBadge>
      </FacetChip>
      {groups.map((group) => (
        <FacetChip
          key={group.key}
          active={value === group.key}
          colorClass={COLOR_CLASS[group.color]}
          onClick={() => onChange(group.key)}
        >
          {group.label}
          <CountBadge active={value === group.key}>{counts[group.key] ?? 0}</CountBadge>
        </FacetChip>
      ))}
    </div>
  )
}

function FacetChip({
  active,
  colorClass,
  onClick,
  children,
}: Readonly<{
  active: boolean
  colorClass?: { bg: string; border: string }
  onClick: () => void
  children: ReactNode
}>) {
  return (
    <button
      type="button"
      aria-pressed={active}
      onClick={onClick}
      className={cn(
        "inline-flex shrink-0 items-center gap-1 rounded-full border px-3 py-1 text-[12px] font-medium transition-colors",
        active && colorClass
          ? cn(colorClass.bg, colorClass.border, "text-background")
          : active
            ? "border-transparent bg-primary text-primary-foreground"
            : "border-border bg-card text-foreground hover:bg-accent",
      )}
    >
      {children}
    </button>
  )
}

function CountBadge({ active, children }: Readonly<{ active: boolean; children: ReactNode }>) {
  return (
    <span className={cn("font-mono text-[10px]", active ? "text-background/80" : "text-muted-foreground")}>
      {children}
    </span>
  )
}

